package com.paytaxihub.entity;
import jakarta.persistence.*;
@Entity @Table(name="Driver") public class Driver { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer driverId; @OneToOne @JoinColumn(name="user_id") private User user; private String saIdNumber,prdpNumber; @ManyToOne @JoinColumn(name="fleet_owner_id") private FleetOwner fleetOwner; @Enumerated(EnumType.STRING) private KycStatus kycStatus; public enum KycStatus{Pending,Verified,Rejected} public Driver(){} public Integer getDriverId(){return driverId;} public void setDriverId(Integer v){driverId=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getSaIdNumber(){return saIdNumber;} public void setSaIdNumber(String v){saIdNumber=v;} public String getPrdpNumber(){return prdpNumber;} public void setPrdpNumber(String v){prdpNumber=v;} public FleetOwner getFleetOwner(){return fleetOwner;} public void setFleetOwner(FleetOwner v){fleetOwner=v;} public KycStatus getKycStatus(){return kycStatus;} public void setKycStatus(KycStatus v){kycStatus=v;} }
